BEGIN TRANSACTION;
CREATE TABLE dim_cooperado (
            cooperado_id INTEGER,
            nome TEXT,
            documento TEXT,
            tipo_pessoa TEXT,
            faixa_renda TEXT,
            porte TEXT,
            data_nascimento TEXT,
            telefone TEXT,
            email TEXT,
            sexo TEXT,
            cidade TEXT,
            uf TEXT,
            data_associacao TEXT
        );
CREATE TABLE dim_pa (
            pa_id INTEGER PRIMARY KEY,
            nome_pa TEXT,
            cidade TEXT,
            uf TEXT,
            regiao TEXT
        );
CREATE TABLE dim_produto (
            produto_id INTEGER PRIMARY KEY,
            nome_produto TEXT,
            categoria TEXT
        );
CREATE TABLE fato_contrato (
            contrato_id INTEGER PRIMARY KEY,
            cooperado_id INTEGER,
            pa_id INTEGER,
            produto_id INTEGER,
            data_contratacao TEXT,
            data_vencimento_final TEXT,
            prazo_meses INTEGER,
            taxa_juros_am REAL,
            valor_contratado TEXT,
            valor_parcela REAL,
            garantia TEXT,
            score_risco INTEGER,
            nivel_risco TEXT
        );
CREATE TABLE fato_parcela (
            parcela_id INTEGER PRIMARY KEY,
            contrato_id INTEGER,
            numero_parcela INTEGER,
            data_vencimento TEXT,
            valor_parcela REAL,
            data_pagamento TEXT,
            valor_pago REAL
        );
CREATE TABLE meta_mensal (
            mes TEXT,
            pa_id INTEGER,
            meta_saldo REAL,
            meta_volume_concedido REAL,
            teto_inadimplencia_90 REAL
        );
COMMIT;
